#include <iostream>
#include <string>
using namespace std;

int main() {
    int n;
    cin >> n;
    int count = 0;
    for (int i = 0; i < n; ++i) {
        string s;
        cin >> s;
        if (s == "For") {
            count += 1;
        }
    }
    if (count > n / 2) {
        cout << "Yes\n";
    } else {
        cout << "No\n";
    }
    return 0;
}

